(* [comment removed for export] *)
Lemma round2 : forall p cf, AT 0xcd38c (fun st => st = 2) p cf -> as_SR H (RES p) cf.
Proof.
  open_X. intros p cf ATc.
  eapply (ah_seq H HH); [eapply (pf_call H HH MX CX MA MR PF1 PF2 IPF X XOK 0xcd38c 0xcd3a0 2 bp_setup2 ltac:(left; reflexivity) ltac:(clear; lia) ltac:(reflexivity) p cf ATc)|].
  intros [ms mo] (q & MIDc).
  destruct MIDc as (rax & t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & n & s & d & m & E' & XS
                    & VIS & STC & KREL & MP & INVc & PQ & EOUT & PROG & ST11). cbn [cfg_ms cfg_model] in *. cbv beta in STC.
  pose proof INVc as (MI & ST & ERR & AUX & RH & FR & SD & PC & EC & EOK & RDI & HC & FTS & U & HO & L & BUD & FSX & INX & XP & ALOK & AMON & PR).
  pose proof FR as (j0 & j160 & j184 & ja & j48 & jb & j80 & jc & j112 & LOC & _).
  apply (proj1 (frame_split H MX CX X XOK m q)) in FR. destruct FR as (FR4 & FRF & IN).
  assert (IK : inv_k H X m (ps_rdi d) XS) by exact (conj ERR (conj AUX (conj FR4 (conj FRF (conj SD (conj RDI (conj FTS (conj FSX (conj INX XP))))))))).
  pose proof SD as (RF & AC & SK & ACP & ACE & ACW & SVE & SVW).
  pose proof (env_facts H HH MX CX X XOK) as (Pl & Ph & APP & FOP & El & Eh & APE & FOE & Wl & Wh & APW & FOW & CEIL & LO & SPAR & SPH).
  pose proof (stat_open H MX CX X XOK) as (N1 & _ & _ & PAL & EAL & DPE & QP & QE & AL16 & SHI & NR & SPB & TP & MXLE & CXLE).
  rewrite BPUT_STACK_val in LO. unfold X8_BP_put4.p1 in PR. pose proof aceil_facts as (AF1 & _).
  pose proof L as (PCOK & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & HL8 & _).
  destruct d as [c S1 L1 ns1 ls1 em1 h u es insz g rdi LBn A]. cbn [ps_c ps_S ps_L ps_ns ps_ls ps_em ps_h ps_u ps_es ps_insz ps_g ps_rdi ps_LBn ps_A] in *.
  assert (SPA16 : spa mod 16 = 0) by (clear - SPA32; Z.div_mod_to_equations; lia).
  (* [comment removed for export] *)
  eapply (ahh_evt_then H HH); [exact KREL| exact VIS| eapply bp_ec2; [exact LOC| exact EC| exact EOK| exact EOUT| exact ACE| exact EAL| exact MI]|].
  cbv beta. intros msF1 mo1 KREL1 MP1 (a0' & a1' & [[-> VIS1]|[HF VIS1]]).
  - (* [comment removed for export] *)
    eapply (ahh_evt_then H HH); [exact KREL1| exact VIS1| apply bp_setupfh|].
    intros msF2 mo2 KREL2 MP2 VIS2. cbv beta in VIS2.
    destruct (ec_CB24 _ _ _ EC) as [ej ECb].
    eapply (ahh_evt_then H HH); [exact KREL2| exact VIS2| |].
    { eapply (FH _ (wz spa) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ m P E lo shi c pad7 pad2 ej g); unfold wz; rewrite ?unsigned_lit by (clear - SPAR CEIL LO AF1 SPH; lia).
      - exact PC. - exact PCOK. - exact ECb. - exact HC. - destruct U as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & XS2); exact XS2. - exact ST.
      - unfold st_pure, FH_STACK, AASSIGN_STACK, AINTRIN_STACK. rewrite ?unsigned_lit by (clear - SPAR CEIL LO AF1 SPH; lia).
        repeat split; first [ assumption | exact SPA16 | (eapply aapp_sub; [exact APP| clear; lia| unfold PARSER_SIZE; clear; lia])
                            | (unfold PARSER_SIZE in DPE; clear - DPE; lia) | (clear - LO SPAR SHI CEIL AF1; lia) ].
      - exact MI. - exact AC. - exact SK.
      - eapply accessible_sub; [exact ACP| clear; lia| unfold PARSER_SIZE; clear; lia| clear; lia].
      - exact ACE.
      - exact (aobj_shvis H HH _ _ _ _ P 80 RH RF (aobj_sub _ _ _ _ P 80 (ao_up H X LBn _ _ AOP) ltac:(clear; lia) ltac:(unfold PARSER_SIZE; clear; lia)) ltac:(clear; lia)).
      - exact SVE. }
    intros msF3 mo3 KREL3 MP3 PO3. unfold fh_post in PO3.
    destruct PO3 as (u0 & u1 & u2 & b0 & b1 & b2 & b3 & b4 & b5 & b6 & b7 & u3 & u4 & u5 & u6 & m2 & VIS3 & MU2 & WM2 & MI2 & ST2 & PC2 & EC2 & HC2 & XS2' & AC2 & SK2).
    unfold body_W in MU2. unfold wz in MU2, ST2. rewrite unsigned_lit in MU2 by (clear - SPAR CEIL LO AF1 SPH; lia). rewrite unsigned_lit in ST2 by (clear - SPAR CEIL LO AF1 SPH; lia).
    replace (ret_pc (wz 0xcd3e4)) with (wz 0xcd3e4 : word) in VIS3 by (symmetry; unfold wz; apply ret_pc_even; [clear; lia| reflexivity]).
    (* [comment removed for export] *)
    assert (FW2 : Forall (wg5 H X) [(lo, spa); (P, P + 80); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64)]%Z).
    { unfold wg5. apply Forall_cons; [left; cbn [fst snd]; clear - CEIL SPAR; lia|]. apply Forall_cons; [right; right; left; cbn [fst snd]; clear; lia|].
      apply Forall_cons; [right; right; right; left; cbn [fst snd]; split; reflexivity|]. apply Forall_cons; [right; right; right; right; cbn [fst snd]; split; reflexivity| apply Forall_nil]. }
    pose proof (wg4_wg H HH MX CX X XOK _ (wg5_wg4 H X _ FW2)) as FW2g.
    pose proof (keep_k H HH MX CX X XOK _ _ _ _ _ _ _ FW2 MU2 WM2 RH IK) as IK2.
    pose proof (keep_U H HH MX CX X XOK _ _ _ _ _ (mkPST c S1 L1 ns1 ls1 em1 h u es insz g rdi LBn A) FW2g MU2 WM2 RH L U) as U2.
    pose proof (keep_hdr H HH MX CX X XOK _ _ _ _ _ (mkPST c S1 L1 ns1 ls1 em1 h u es insz g rdi LBn A) FW2g MU2 WM2 RH L HO) as HO2.
    pose proof (keep_rheap H HH MX CX X XOK _ _ _ _ _ FW2g MU2 WM2 RH) as RH2.
    pose proof IK2 as (ERR2 & AUX2 & FR42 & FRF2 & SD2 & RDI2 & FTS2 & FSX2 & INX2 & XP2). pose proof SD2 as (_ & _ & _ & _ & ACE2 & _).
    assert (IN2 : rw_cells asegs m2 (spa + 208) [C8 (wz q)]).
    { eapply rw_cells_transport; [exact IN| exact MU2| exact WM2|]. cbn [cells_size csize Nat.add]. unfold PARSER_SIZE, AG_HTTP_CAT in *. clear - CEIL Ph Eh SPAR LO AF1. cbn. repeat split; lia. }
    pose proof FR42 as (j0' & j160' & j184' & LOC2 & _).
    pose proof (proj2 (bp_locals_split H MX CX X XOK m2 j0' j160' j184' q) (conj LOC2 IN2)) as LOC2f.
    pose proof (fh_facts c PCOK STC) as (PCOK' & HLEQ & SKEQ & ST2' & LEN' & EOK' & EOUT' & ST11' & _).
    set (d2 := mkPST (snd (fh_res c)) S1 L1 ns1 ls1 em1 h u es insz (fh_assigns c || g) rdi LBn A).
    assert (INV2 : INV s d2 m2 q (fst (fh_res c)) XS).
    { unfold bput_inv. subst d2. cbn [ps_c ps_S ps_L ps_ns ps_ls ps_em ps_h ps_u ps_es ps_insz ps_g ps_rdi ps_LBn ps_A].
      split; [exact MI2|]. split; [exact ST2|]. split; [exact ERR2|]. split; [exact AUX2|]. split; [exact RH2|].
      split; [apply (proj2 (frame_split H MX CX X XOK m2 q)); exact (conj FR42 (conj FRF2 IN2))|].
      split; [exact SD2|]. split; [exact PC2|]. split; [exact EC2|]. split; [exact EOK'|]. split; [exact RDI2|]. split; [exact HC2|]. split; [exact FTS2|].
      split; [exact U2|]. split; [exact HO2|].
      split; [exact (PutL_core (mkPST c S1 L1 ns1 ls1 em1 h u es insz g rdi LBn A) (snd (fh_res c)) L PCOK' SKEQ ltac:(cbn [ps_c]; clear - ST2'; lia) LEN' ltac:(cbn [ps_c] in HLEQ; rewrite HLEQ; intros _; apply HL8; rewrite STC; clear; lia))|].
      split; [exact (PutB_core (mkPST c S1 L1 ns1 ls1 em1 h u es insz g rdi LBn A) (snd (fh_res c)) (fh_assigns c || g) q BUD HLEQ ltac:(cbn [ps_c]; rewrite STC; clear; lia) ltac:(cbn [ps_c]; clear - ST2'; lia))|].
      split; [exact FSX2|]. split; [exact INX2|]. split; [exact XP2|]. split; [exact ALOK|]. split; [exact AMON| exact PR]. }
    (* [comment removed for export] *)
    eapply (ahh_evt_then H HH); [exact KREL3| exact VIS3| eapply bp_ec2b; [exact LOC2f| exact EC2| exact EOK'| exact EOUT'| exact ACE2| exact EAL| exact MI2]|].
    cbv beta. intros msF4 mo4 KREL4 MP4 (a0'' & a1'' & [[CLR VIS4]|[HF VIS4]]).
    + apply (sr_tail H HH MX CX MA MR X XOK p q). unfold put_mid. cbn [cfg_ms cfg_model].
      exists (wz 0xcd3e4), u0, u1, u2, a0'', a1'', b2, b3, b4, b5, b6, b7, u3, u4, u5, u6, n, s, d2, m2, (fst (fh_res c)), XS.
      split; [exact VIS4|]. split; [exact CLR|]. split; [exact KREL4|].
      split; [eapply (ah_mpres_trans H HH); [exact MP| eapply (ah_mpres_trans H HH); [exact MP1| eapply (ah_mpres_trans H HH); [exact MP2| eapply (ah_mpres_trans H HH); [exact MP3| exact MP4]]]]|].
      split; [exact INV2|]. split; [exact PQ|]. split; [exact EOUT'|].
      split; [intros _; destruct (PROG eq_refl) as [K|K]; [left; exact K| exfalso; rewrite STC in K; clear - K; lia]| exact ST11'].
    + eapply (ah_seq H HH); [apply (sr_done H HH MX CX MA MR X XOK (fun _ _ => True) p q)| intros c' D; apply (ah_done H HH); left; exact D]. unfold put_mid. cbn [cfg_ms cfg_model].
      exists (wz 0xcd3e4), u0, u1, u2, a0'', a1'', b2, b3, b4, b5, b6, b7, u3, u4, u5, u6, n, s, d2, m2, (fst (fh_res c)), XS.
      split; [exact VIS4|]. split; [exact I|]. split; [exact KREL4|].
      split; [eapply (ah_mpres_trans H HH); [exact MP| eapply (ah_mpres_trans H HH); [exact MP1| eapply (ah_mpres_trans H HH); [exact MP2| eapply (ah_mpres_trans H HH); [exact MP3| exact MP4]]]]|].
      split; [exact INV2|]. split; [exact PQ|]. split; [exact EOUT'|].
      split; [intros _; destruct (PROG eq_refl) as [K|K]; [left; exact K| exfalso; rewrite STC in K; clear - K; lia]| exact ST11'].
  - (* [comment removed for export] *)
    eapply (ah_seq H HH); [apply (sr_done H HH MX CX MA MR X XOK (fun c E' => pc_state c = 2) p q)| intros c' D; apply (ah_done H HH); left; exact D]. unfold put_mid. cbn [cfg_ms cfg_model].
    exists rax, t0, t1, t2, a0', a1', a2, a3, a4, a5, a6, a7, t3, t4, t5, t6, n, s, (mkPST c S1 L1 ns1 ls1 em1 h u es insz g rdi LBn A), m, E', XS.
    split; [exact VIS1|]. split; [exact STC|]. split; [exact KREL1|]. split; [eapply (ah_mpres_trans H HH); [exact MP| exact MP1]|].
    split; [exact INVc|]. split; [exact PQ|]. split; [exact EOUT|]. split; [exact PROG| exact ST11].
Qed.

